     1→/**
     2→ * Test coverage cache for daemon performance optimization.
     3→ *
     4→ * Caches scanTestCoverage() results to avoid re-scanning test files
     5→ * on every API request. The cache is per-project-directory and supports:
     6→ * - TTL-based expiration (default 60 seconds)
     7→ * - Explicit invalidation for file watcher integration
     8→ *
     9→ * @module coverage-cache
    10→ */
    11→
    12→import { scanTestCoverage } from "./validate.js";
    13→
    14→/**
    15→ * Cached coverage data with metadata
    16→ */
    17→interface CacheEntry {
    18→  /** The actual coverage set */
    19→  coverage: Set<string>;
    20→  /** Timestamp when cache was populated */
    21→  cachedAt: number;
    22→  /** Promise for in-flight scan (prevents duplicate parallel scans) */
    23→  pending?: Promise<Set<string>>;
    24→}
    25→
    26→/**
    27→ * Default TTL in milliseconds (60 seconds)
    28→ */
    29→const DEFAULT_TTL_MS = 60_000;
    30→
    31→/**
    32→ * Per-project cache storage
    33→ * Key: normalized root directory path
    34→ */
    35→const cache = new Map<string, CacheEntry>();
    36→
    37→/**
    38→ * Configurable TTL (for testing)
    39→ */
    40→let ttlMs = DEFAULT_TTL_MS;
    41→
    42→/**
    43→ * Normalize a directory path for use as cache key.
    44→ * Removes trailing slashes for consistency.
    45→ */
    46→function normalizePath(dir: string): string {
    47→  return dir.endsWith("/") ? dir.slice(0, -1) : dir;
    48→}
    49→
    50→/**
    51→ * Check if a cache entry is still valid based on TTL.
    52→ */
    53→function isValid(entry: CacheEntry): boolean {
    54→  return Date.now() - entry.cachedAt < ttlMs;
    55→}
    56→
    57→/**
    58→ * Get test coverage for a project directory, using cache when available.
    59→ *
    60→ * This is the primary API for daemon routes. It:
    61→ * 1. Returns cached results if valid
    62→ * 2. Returns in-flight scan result if a scan is already in progress
    63→ * 3. Otherwise initiates a new scan and caches the result
    64→ *
    65→ * @param rootDir - Project root directory containing tests/
    66→ * @returns Set of covered AC references (e.g., "@spec-ref ac-1")
    67→ */
    68→export async function getCachedTestCoverage(
    69→  rootDir: string
    70→): Promise<Set<string>> {
    71→  const key = normalizePath(rootDir);
    72→  const existing = cache.get(key);
    73→
    74→  // Return cached result if valid
    75→  if (existing && isValid(existing) && !existing.pending) {
    76→    return existing.coverage;
    77→  }
    78→
    79→  // Return in-flight scan if one exists (prevents duplicate parallel scans)
    80→  if (existing?.pending) {
    81→    return existing.pending;
    82→  }
    83→
    84→  // Initiate new scan
    85→  const scanPromise = scanTestCoverage(rootDir);
    86→
    87→  // Store pending promise to prevent parallel scans
    88→  const entry: CacheEntry = existing || {
    89→    coverage: new Set(),
    90→    cachedAt: 0,
    91→  };
    92→  entry.pending = scanPromise;
    93→  cache.set(key, entry);
    94→
    95→  try {
    96→    const coverage = await scanPromise;
    97→    // Update cache with result
    98→    entry.coverage = coverage;
    99→    entry.cachedAt = Date.now();
   100→    entry.pending = undefined;
   101→    return coverage;
   102→  } catch (error) {
   103→    // Clear pending on error, allow retry
   104→    entry.pending = undefined;
   105→    throw error;
   106→  }
   107→}
   108→
   109→/**
   110→ * Invalidate the test coverage cache for a specific project or all projects.
   111→ *
   112→ * Call this when test files change (via file watcher) to ensure
   113→ * fresh coverage data on next request.
   114→ *
   115→ * @param rootDir - Optional project root directory. If omitted, clears all caches.
   116→ */
   117→export function invalidateTestCoverageCache(rootDir?: string): void {
   118→  if (rootDir) {
   119→    const key = normalizePath(rootDir);
   120→    cache.delete(key);
   121→  } else {
   122→    cache.clear();
   123→  }
   124→}
   125→
   126→/**
   127→ * Set the cache TTL (for testing purposes).
   128→ *
   129→ * @param ms - TTL in milliseconds
   130→ */
   131→export function setTestCoverageCacheTTL(ms: number): void {
   132→  ttlMs = ms;
   133→}
   134→
   135→/**
   136→ * Reset the cache TTL to default (for testing purposes).
   137→ */
   138→export function resetTestCoverageCacheTTL(): void {
   139→  ttlMs = DEFAULT_TTL_MS;
   140→}
   141→
   142→/**
   143→ * Get current cache statistics (for debugging/monitoring).
   144→ */
   145→export function getTestCoverageCacheStats(): {
   146→  entries: number;
   147→  ttlMs: number;
   148→} {
   149→  return {
   150→    entries: cache.size,
   151→    ttlMs,
   152→  };
   153→}
   154→
